<script setup>
import {computed} from 'vue';import {EditorContent,useEditor} from '@tiptap/vue-3';import {ArrowLeft,ArrowUpRight} from '@lucide/vue';import {extensions} from './editor.mjs';
const props=defineProps({guide:Object,site:Object,state:Object,canPublish:Boolean,busy:Boolean,imageSource:Function});const emit=defineEmits(['back','publish']);
const editor=useEditor({extensions:extensions(props.imageSource),content:props.guide?.body||'',contentType:'markdown',editable:false,editorProps:{attributes:{class:'guide-document','aria-label':'Vorschau des gespeicherten Entwurfs'}}});
const acknowledged=computed(()=>props.state.publishEnabled&&props.state.publication);
</script>
<template>
 <button class="quiet" @click="emit('back')"><ArrowLeft :size="17"/> Zurück zum Bearbeiten</button><div class="page-heading"><div><h1>Vorschau & Veröffentlichung</h1><p>{{guide?.title||'Startseite, Navigation & Footer'}}</p></div></div>
 <div class="release-summary"><strong>Du prüfst den gespeicherten Entwurf.</strong><p>Es wird ausschließlich {{guide?'dieser Beitrag mit seinen referenzierten Bildern':'die Website-Konfiguration mit dem Startseitenbild'}} übernommen. Andere Entwürfe und redaktionelle Kommentare bleiben unveröffentlicht.</p><p v-if="guide?.review==='pending'">Die fachliche Prüfung ist noch offen. Veröffentlichst du trotzdem, bleibt dieser Prüfstatus sichtbar.</p><small>Entwurf {{state.head.slice(0,7)}} · Online-Stand {{state.publication?.head?.slice(0,7)||'nicht verfügbar'}}</small></div>
 <template v-if="guide"><EditorContent :editor="editor" class="release-document"/></template>
 <div v-else class="site-preview"><nav><strong>{{site.brand}}</strong><span v-for="link in site.navigation">{{link.text}} <small>{{link.link}}</small></span></nav><div class="site-preview-hero" :style="{backgroundImage:`linear-gradient(90deg,#0b0c0eee,#0b0c0e66),url(${imageSource(site.home.image)})`}"><h2>{{site.home.title}}<br><em>{{site.home.emphasis}}</em></h2><p>{{site.home.intro}}</p><span>{{site.home.actionText}}</span></div><h2>{{site.home.topicsTitle}}</h2><p>{{site.home.workNote}}</p><h2>{{site.home.featureTitle}}</h2><p>{{site.home.featureText}}</p><p>{{site.home.featureLabel}} → {{site.home.featureLink}}</p><small>{{site.home.featureNote}}</small><h2>{{site.home.bottomTitle}}</h2><p>{{site.home.bottomText}}</p><p v-for="link in site.home.bottomLinks">{{link.text}} → {{link.link}}</p><footer>{{site.footer.message}}<br>{{site.footer.copyright}}</footer></div>
 <div class="publish-bar"><p v-if="!canPublish">Dein Zugang darf nicht veröffentlichen. Reiche den Beitrag im Editor zur Freigabe ein.</p><p v-else-if="!acknowledged">Lokale Vorschau: Veröffentlichungen sind hier gesperrt.</p><p v-else>Nach deiner Bestätigung startet GitHub den Website-Build. Bis er erfolgreich ist, bleibt die bisherige Website online.</p><button class="primary" :disabled="busy||!canPublish||!acknowledged" @click="emit('publish')">{{busy?'Wird übernommen …':'Jetzt veröffentlichen'}}</button></div>
</template>
